{
  "timeline": [
    {
      "date": "1908-03-09",
      "headline": "Club Founded",
      "text": "Football Club Internazionale Milano, commonly referred to as Inter Milan, was founded on March 9, 1908, following a split from the Milan Cricket and Football Club (now AC Milan) over the signing of foreign players."
    },
    {
      "date": "1910",
      "headline": "First Serie A Title",
      "text": "Inter Milan won their first Serie A title in 1910, marking the club's first major success in Italian football."
    },
    {
      "date": "1920",
      "headline": "Second Serie A Title",
      "text": "Inter Milan secured their second Serie A championship in 1920, further establishing themselves as a dominant force in Italian football."
    },
    {
      "date": "1930",
      "headline": "Name Change to Ambrosiana",
      "text": "Under the Fascist regime, the club was forced to merge with Unione Sportiva Milanese and was renamed Società Sportiva Ambrosiana."
    },
    {
      "date": "1938",
      "headline": "Return to Original Name",
      "text": "The club reverted to its original name, Internazionale, in 1938, after the fall of the Fascist regime."
    },
    {
      "date": "1964",
      "headline": "First European Cup Victory",
      "text": "Inter Milan won their first European Cup (now UEFA Champions League) in 1964, defeating Real Madrid 3-1 in the final."
    },
    {
      "date": "1965",
      "headline": "Second European Cup Victory",
      "text": "Inter Milan successfully defended their European Cup title in 1965, defeating Benfica 1-0 in the final."
    },
    {
      "date": "2010-05-22",
      "headline": "UEFA Champions League Victory",
      "text": "Inter Milan won the UEFA Champions League in 2010, defeating Bayern Munich 2-0 in the final, completing a historic treble of Serie A, Coppa Italia, and Champions League titles in the same season."
    },
    {
      "date": "2021",
      "headline": "Serie A Title",
      "text": "Inter Milan won the Serie A title in 2021, ending Juventus's nine-year dominance in the league."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1980-06-17",
      "headline": "Birth",
      "text": "Venus Ebony Starr Williams was born in Lynwood, California, United States."
    },
    {
      "date": "1994-10-31",
      "headline": "Professional Debut",
      "text": "Venus Williams made her professional tennis debut at the age of 14 at the Bank of the West Classic in Oakland, California."
    },
    {
      "date": "1997",
      "headline": "First Grand Slam Final",
      "text": "Venus Williams reached her first Grand Slam final at the US Open, where she was defeated by Martina Hingis."
    },
    {
      "date": "2000",
      "headline": "First Grand Slam Singles Title",
      "text": "Venus Williams won her first Grand Slam singles title at Wimbledon, defeating Lindsay Davenport in the final."
    },
    {
      "date": "2000",
      "headline": "Olympic Gold Medal",
      "text": "Venus Williams won the gold medal in singles at the Sydney Olympics, becoming the first woman to win both Wimbledon and Olympic singles titles in the same year."
    },
    {
      "date": "2000",
      "headline": "US Open Champion",
      "text": "Venus Williams won her first US Open singles title, defeating Lindsay Davenport in the final."
    },
    {
      "date": "2001",
      "headline": "Wimbledon and US Open Titles",
      "text": "Venus Williams successfully defended her titles at both Wimbledon and the US Open, winning both Grand Slam tournaments for the second consecutive year."
    },
    {
      "date": "2002",
      "headline": "World No. 1 Ranking",
      "text": "Venus Williams became the first African American woman to be ranked No. 1 in the world in singles in the Open Era."
    },
    {
      "date": "2005",
      "headline": "Wimbledon Champion",
      "text": "Venus Williams won her third Wimbledon singles title, defeating Lindsay Davenport in the longest women's final in Wimbledon history."
    },
    {
      "date": "2007",
      "headline": "Fourth Wimbledon Title",
      "text": "Venus Williams won her fourth Wimbledon singles title, defeating Marion Bartoli in the final."
    },
    {
      "date": "2008",
      "headline": "Fifth Wimbledon Title",
      "text": "Venus Williams won her fifth Wimbledon singles title, defeating her sister Serena Williams in the final."
    },
    {
      "date": "2008",
      "headline": "Olympic Gold Medal in Doubles",
      "text": "Venus Williams, partnering with her sister Serena Williams, won the gold medal in women's doubles at the Beijing Olympics."
    },
    {
      "date": "2012",
      "headline": "Olympic Gold Medal in Doubles",
      "text": "Venus Williams, alongside her sister Serena, won the gold medal in women's doubles at the London Olympics."
    },
    {
      "date": "2017",
      "headline": "Australian Open and Wimbledon Finals",
      "text": "Venus Williams reached the finals of both the Australian Open and Wimbledon, marking her return to top form."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1971-11-24",
      "headline": "Hijacking of Flight 305",
      "text": "An unidentified man, later known as D. B. Cooper, hijacked Northwest Orient Airlines Flight 305, a Boeing 727 aircraft, during its flight from Portland, Oregon, to Seattle, Washington. He claimed to have a bomb and demanded $200,000 in ransom and four parachutes."
    },
    {
      "date": "1971-11-24",
      "headline": "Ransom Delivered",
      "text": "Upon landing in Seattle, the ransom money and parachutes were delivered to Cooper. He released the 36 passengers in exchange for the money and parachutes but kept several crew members on board."
    },
    {
      "date": "1971-11-24",
      "headline": "Second Flight to Mexico City",
      "text": "Cooper instructed the flight crew to refuel the aircraft and take off for Mexico City, with a planned refueling stop in Reno, Nevada."
    },
    {
      "date": "1971-11-24",
      "headline": "Parachute Jump",
      "text": "Approximately 30 minutes after taking off from Seattle, Cooper opened the aircraft's aft door and deployed the staircase. He parachuted into the night over southwestern Washington, disappearing without a trace."
    },
    {
      "date": "1980",
      "headline": "Discovery of Ransom Money",
      "text": "A young boy discovered a decaying package containing $5,800 in $20 bills, identified as part of the ransom money, buried along the Columbia River in Washington."
    }
  ]
}

