{
  "timeline": [
    {
      "date": "-02000",
      "headline": "Earliest Settlement",
      "text": "The earliest settlement in Jerusalem dates back to the early Bronze Age, around 2000 BCE, when the city was known as Urusalim."
    },
    {
      "date": "-01000",
      "headline": "City of David",
      "text": "Around 1000 BCE, King David conquered Jerusalem and established it as the capital of the Kingdom of Israel."
    },
    {
      "date": "-00960",
      "headline": "First Temple Built",
      "text": "Solomon, David's son, built the First Temple in Jerusalem, which became the central place of worship for the Israelites."
    },
    {
      "date": "-00586",
      "headline": "Destruction of the First Temple",
      "text": "The Babylonians, led by King Nebuchadnezzar II, destroyed Jerusalem and the First Temple, leading to the Babylonian Exile."
    },
    {
      "date": "-00516",
      "headline": "Second Temple Constructed",
      "text": "The Second Temple was completed in Jerusalem under the auspices of the Persian Empire, following the return of the Jewish exiles."
    },
    {
      "date": "-00337",
      "headline": "Conquest by Alexander the Great",
      "text": "Jerusalem came under the control of Alexander the Great during his conquests, marking the beginning of Hellenistic influence."
    },
    {
      "date": "-00167",
      "headline": "Maccabean Revolt",
      "text": "The Maccabean Revolt against the Seleucid Empire led to the rededication of the Second Temple, celebrated as Hanukkah."
    },
    {
      "date": "-00063",
      "headline": "Roman Conquest",
      "text": "Pompey the Great captured Jerusalem, bringing it under Roman control."
    },
    {
      "date": "0070",
      "headline": "Destruction of the Second Temple",
      "text": "The Romans, under Emperor Titus, destroyed the Second Temple during the Siege of Jerusalem, a pivotal event in Jewish history."
    },
    {
      "date": "0135",
      "headline": "Aelia Capitolina",
      "text": "Emperor Hadrian rebuilt Jerusalem as a Roman colony named Aelia Capitolina, banning Jews from the city."
    },
    {
      "date": "0638",
      "headline": "Islamic Conquest",
      "text": "Jerusalem was captured by the Rashidun Caliphate under Caliph Umar, marking the beginning of Islamic rule."
    },
    {
      "date": "1099",
      "headline": "Crusader Conquest",
      "text": "The First Crusade captured Jerusalem, establishing it as the capital of the Kingdom of Jerusalem."
    },
    {
      "date": "1187",
      "headline": "Saladin's Capture",
      "text": "Saladin, the Muslim leader, recaptured Jerusalem from the Crusaders, restoring Islamic rule."
    },
    {
      "date": "1517",
      "headline": "Ottoman Rule",
      "text": "Jerusalem became part of the Ottoman Empire, which ruled the city for four centuries."
    },
    {
      "date": "1917",
      "headline": "British Capture",
      "text": "During World War I, British forces captured Jerusalem from the Ottomans, leading to the British Mandate."
    },
    {
      "date": "1948",
      "headline": "Division of Jerusalem",
      "text": "Following the 1948 Arab-Israeli War, Jerusalem was divided between Israel and Jordan."
    },
    {
      "date": "1967",
      "headline": "Six-Day War",
      "text": "Israel captured East Jerusalem from Jordan during the Six-Day War, unifying the city under Israeli control."
    },
    {
      "date": "1980",
      "headline": "Jerusalem Law",
      "text": "Israel passed the Jerusalem Law, declaring the city its undivided capital, a move not widely recognized internationally."
    }
  ]
}

