{
  "timeline": [
    {
      "date": "-0338",
      "headline": "Battle of Chaeronea",
      "text": "The region of Macedonia, which includes present-day North Macedonia, was part of the Kingdom of Macedon. In 338 BCE, King Philip II of Macedon defeated the Greek city-states at the Battle of Chaeronea, establishing Macedonian dominance over Greece."
    },
    {
      "date": "-0334",
      "headline": "Alexander the Great's Campaigns",
      "text": "Alexander the Great, son of Philip II, began his campaign to conquer the Persian Empire. His conquests spread Hellenistic culture throughout the known world, including the region of Macedonia."
    },
    {
      "date": "0146",
      "headline": "Roman Conquest",
      "text": "The region became part of the Roman Empire after the Roman conquest of Macedonia in 146 BCE, following the defeat of the Macedonian kingdom."
    },
    {
      "date": "0395",
      "headline": "Division of the Roman Empire",
      "text": "Upon the division of the Roman Empire, the region became part of the Eastern Roman Empire, later known as the Byzantine Empire."
    },
    {
      "date": "0867",
      "headline": "Byzantine Control",
      "text": "The region remained under Byzantine control, experiencing periods of stability and conflict with neighboring powers."
    },
    {
      "date": "1018",
      "headline": "Annexation by the Byzantine Empire",
      "text": "The region was annexed by the Byzantine Empire after the defeat of the First Bulgarian Empire."
    },
    {
      "date": "1395",
      "headline": "Ottoman Rule",
      "text": "The region fell under Ottoman rule, which lasted for over five centuries, significantly influencing the cultural and demographic landscape."
    },
    {
      "date": "1912",
      "headline": "Balkan Wars",
      "text": "The Balkan Wars resulted in the end of Ottoman rule in the region, with the territory being divided among the Balkan states."
    },
    {
      "date": "1913",
      "headline": "Treaty of Bucharest",
      "text": "The Treaty of Bucharest in 1913 divided the region of Macedonia among Greece, Serbia, and Bulgaria, with the area now known as North Macedonia becoming part of Serbia."
