    {
      "date": "1783",
      "headline": "First Theoretical Concept",
      "text": "John Michell proposed the concept of 'dark stars' with gravity so strong that even light could not escape."
    },
    {
      "date": "1915",
      "headline": "General Relativity",
      "text": "Albert Einstein published his theory of general relativity, which laid the groundwork for the modern understanding of black holes."
