    {
      "date": "1916",
      "headline": "Schwarzschild Solution",
      "text": "Karl Schwarzschild found the first exact solution to the Einstein field equations, describing what would later be known as a black hole."
    },
    {
      "date": "1931",
      "headline": "Chandrasekhar Limit",
      "text": "Subrahmanyan Chandrasekhar calculated the maximum mass of a stable white dwarf star, beyond which it would collapse, leading to the concept of black holes."
    },
    {
      "date": "1963",
      "headline": "Kerr Black Hole",
      "text": "Roy P. Kerr discovered the exact solution of the Einstein field equations for a rotating black hole."
    },
    {
      "date": "1967",
      "headline": "Term 'Black Hole' Coined",
      "text": "Physicist John Archibald Wheeler popularized the term 'black hole' during a lecture."
    },
    {
      "date": "1971",
      "headline": "First Black Hole Candidate",
      "text": "Cygnus X-1 was identified as the first strong black hole candidate."
    },
    {
      "date": "1974",
      "headline": "Hawking Radiation",
      "text": "Stephen Hawking proposed that black holes can emit radiation due to quantum effects near the event horizon, now known as Hawking radiation."
    },
    {
      "date": "2019-04-10",
      "headline": "First Image of a Black Hole",
      "text": "The Event Horizon Telescope collaboration released the first-ever image of a black hole, located in the center of the galaxy M87."
    }
  ]
}

