      "date": "1940-05-20",
      "headline": "Establishment of Auschwitz I",
      "text": "Auschwitz I, the main camp, was established by Nazi Germany in the town of Oświęcim, Poland. It initially served as a detention center for political prisoners."
    },
    {
      "date": "1941-09",
      "headline": "First Use of Zyklon B",
      "text": "The first experimental gassing using Zyklon B took place at Auschwitz I, marking the beginning of its use as an extermination camp."
    },
    {
      "date": "1941-10",
      "headline": "Construction of Auschwitz II-Birkenau",
      "text": "Construction began on Auschwitz II-Birkenau, which would become the largest of the Auschwitz camps and the primary site of the mass extermination of Jews."
    },
    {
      "date": "1942-03",
      "headline": "First Mass Transport to Auschwitz II-Birkenau",
      "text": "The first mass transport of Jews arrived at Auschwitz II-Birkenau, marking the start of its operation as a major extermination camp."
    },
    {
      "date": "1942-10",
      "headline": "Opening of Auschwitz III-Monowitz",
      "text": "Auschwitz III-Monowitz, a labor camp for the chemical conglomerate IG Farben, was opened. It was part of the industrial exploitation of camp prisoners."
    },
    {
      "date": "1944-05",
      "headline": "Hungarian Jews Deported to Auschwitz",
      "text": "In one of the largest deportations, approximately 430,000 Hungarian Jews were transported to Auschwitz, with most being sent directly to the gas chambers."
    },
    {
      "date": "1944-10-07",
      "headline": "Sonderkommando Revolt",
      "text": "Jewish prisoners in the Sonderkommando, who were forced to work in the gas chambers, staged an uprising. They destroyed one of the crematoria before being subdued."
    },
    {
      "date": "1945-01-27",
      "headline": "Liberation of Auschwitz",
      "text": "The Soviet Red Army liberated Auschwitz, freeing the remaining prisoners. The camp had become a symbol of the Holocaust and the atrocities committed by the Nazis."
    }
  ]
}

