  "timeline": [
    {
      "date": "1865",
      "headline": "Idea for the Statue",
      "text": "The idea for the Statue of Liberty was proposed by French political thinker and abolitionist Édouard René de Laboulaye, who suggested creating a monument to celebrate the centennial of the United States and its enduring democracy."
    },
    {
      "date": "1870",
      "headline": "Design Begins",
      "text": "French sculptor Frédéric Auguste Bartholdi began designing the statue, inspired by the Roman goddess Libertas, the goddess of freedom."
    },
    {
      "date": "1875",
      "headline": "Project Announcement",
      "text": "The project was announced in France, and fundraising efforts began to finance the statue."
    },
    {
      "date": "1876",
      "headline": "Construction Begins",
      "text": "Construction of the statue began in France, with Bartholdi overseeing the creation of the statue's head and torch-bearing arm."
    },
    {
      "date": "1878",
      "headline": "Statue's Head Displayed",
      "text": "The head of the statue was exhibited at the 1878 Paris World's Fair to raise funds and interest in the project."
    },
    {
      "date": "1881",
      "headline": "Gustave Eiffel's Involvement",
      "text": "Engineer Gustave Eiffel, known for the Eiffel Tower, was brought in to design the statue's internal iron framework."
    },
    {
      "date": "1884-07-04",
      "headline": "Completion in France",
      "text": "The statue was completed in France and formally presented to the U.S. Ambassador as a gift from France."
    },
    {
      "date": "1885-06-17",
      "headline": "Arrival in New York",
      "text": "The statue arrived in New York Harbor in 350 individual pieces packed in 214 crates."
    },
    {
      "date": "1886-04",
      "headline": "Assembly on Liberty Island",
      "text": "Assembly of the statue began on Liberty Island, then known as Bedloe's Island."
    },
    {
      "date": "1886-10-28",
      "headline": "Dedication Ceremony",
      "text": "The Statue of Liberty was officially dedicated in a ceremony presided over by President Grover Cleveland."
    },
    {
      "date": "1924",
      "headline": "National Monument Designation",
      "text": "The Statue of Liberty was designated as a National Monument by President Calvin Coolidge."
    },
    {
      "date": "1933",
      "headline": "National Park Service Management",
      "text": "The statue came under the management of the National Park Service."
    },
    {
      "date": "1984",
      "headline": "UNESCO World Heritage Site",
      "text": "The Statue of Liberty was designated a UNESCO World Heritage Site."
    },
    {
      "date": "1986-07-04",
      "headline": "Centennial Restoration",
      "text": "A major restoration of the statue was completed in time for its centennial celebration."
    }
  ]
}

