    {
      "date": "1937-12",
      "headline": "Widespread Rape and Looting",
      "text": "Throughout December, Japanese troops committed widespread rape, looting, and arson across Nanjing, with estimates of rapes ranging from 20,000 to over 80,000."
    },
    {
      "date": "1938-01",
      "headline": "End of the Nanjing Massacre",
      "text": "The massacre continued for six weeks, ending in January 1938, with estimates of the death toll varying from 40,000 to over 300,000."
    },
    {
      "date": "1946",
      "headline": "International Military Tribunal for the Far East",
      "text": "The International Military Tribunal for the Far East estimated that at least 200,000 people were killed during the Nanjing Massacre."
    },
    {
      "date": "1947",
      "headline": "Nanjing War Crimes Tribunal",
