{
  "timeline": [
    {
      "date": "1990",
      "headline": "Introduction of the Human Development Index",
      "text": "The Human Development Index (HDI) was introduced in the first Human Development Report published by the United Nations Development Programme (UNDP). It was developed by Pakistani economist Mahbub ul-Haq, with the goal of shifting the focus of development economics from national income accounting to people-centered policies."
    },
    {
      "date": "1990",
      "headline": "First Human Development Report",
      "text": "The first Human Development Report was published, presenting the HDI as a new way to measure and rank countries' levels of social and economic development based on life expectancy, education, and per capita income indicators."
    },
    {
      "date": "1991",
      "headline": "Second Human Development Report",
      "text": "The second Human Development Report was published, continuing to refine the HDI and its methodology, and expanding the analysis of human development issues."
    },
    {
      "date": "2010",
      "headline": "Introduction of the Inequality-adjusted HDI",
      "text": "The 2010 Human Development Report introduced the Inequality-adjusted Human Development Index (IHDI), which accounts for inequality in the distribution of each dimension of the HDI across the population."
    },
    {
      "date": "2010",
      "headline": "Introduction of the Multidimensional Poverty Index",
      "text": "Alongside the HDI, the 2010 report also introduced the Multidimensional Poverty Index (MPI), which measures poverty by considering multiple deprivations in health, education, and living standards."
    },
    {
      "date": "2014",
      "headline": "Introduction of the Gender Development Index",
      "text": "The Gender Development Index (GDI) was introduced to measure gender inequalities in achievement in the same three basic dimensions of the HDI: health, education, and command over economic resources."
    },
    {
      "date": "2014",
      "headline": "Introduction of the Gender Inequality Index",
      "text": "The Gender Inequality Index (GII) was introduced to reflect gender-based disadvantage in three dimensions – reproductive health, empowerment, and the labor market."
    }
  ]
}

