    },
    {
      "date": "1616",
      "headline": "Arrival of Zhabdrung Ngawang Namgyal",
      "text": "Zhabdrung Ngawang Namgyal, a Tibetan lama, arrived in Bhutan and unified the country, establishing a dual system of government with both secular and religious leaders."
    },
    {
      "date": "1651",
      "headline": "Death of Zhabdrung Ngawang Namgyal",
      "text": "Zhabdrung Ngawang Namgyal passed away, but his death was kept secret for 54 years to maintain stability in Bhutan."
    },
    {
      "date": "1907-12-17",
      "headline": "Establishment of Monarchy",
      "text": "Ugyen Wangchuck was elected as the first Druk Gyalpo (King) of Bhutan, marking the establishment of the hereditary monarchy."
    },
    {
      "date": "1949",
      "headline": "Treaty of Friendship with India",
      "text": "Bhutan signed a treaty with India, which provided for peace and non-interference in each other's internal affairs, while India agreed to guide Bhutan's foreign policy."
    },
    {
      "date": "1971",
      "headline": "UN Membership",
      "text": "Bhutan became a member of the United Nations, marking its entry into the international community."
    },
    {
      "date": "2006-12-14",
      "headline": "Abdication of King Jigme Singye Wangchuck",
      "text": "King Jigme Singye Wangchuck abdicated the throne in favor of his son, Jigme Khesar Namgyel Wangchuck, as part of a transition to a constitutional monarchy."
    },
    {
      "date": "2008",
      "headline": "Adoption of Constitution",
      "text": "Bhutan adopted its first constitution, transitioning from an absolute monarchy to a constitutional monarchy with a parliamentary democracy."
    },
    {
      "date": "2008-03-24",
      "headline": "First Democratic Elections",
      "text": "Bhutan held its first democratic elections, resulting in the Druk Phuensum Tshogpa party winning a majority of the seats in the National Assembly."
