{
  "timeline": [
    {
      "date": "1970",
      "headline": "Emergence of the Sovereign Citizen Movement",
      "text": "The sovereign citizen movement began to appear in the United States in the early 1970s. It is characterized by a pseudolegal belief system that misinterprets common law and claims that individuals are not subject to government statutes unless they consent to them."
    },
    {
      "date": "1980s",
      "headline": "Growth and Spread",
      "text": "During the 1980s, the movement gained traction among anti-government activists, tax protesters, and conspiracy theorists. It attracted individuals who were disillusioned with the government and sought alternative legal theories."
    },
    {
      "date": "1990s",
      "headline": "Increased Legal Challenges",
      "text": "Throughout the 1990s, sovereign citizens became known for filing frivolous lawsuits and engaging in vexatious litigation. Their activities began to draw attention from law enforcement and the legal community."
    },
    {
      "date": "2000s",
      "headline": "Freeman on the Land Movement",
      "text": "In the 2000s, a similar movement known as 'freeman on the land' emerged in Canada. This movement shared many beliefs with the sovereign citizen movement and began to spread to other Commonwealth countries, including Australia, New Zealand, and the United Kingdom."
    },
    {
      "date": "2010",
      "headline": "FBI Designation",
      "text": "In 2010, the FBI described sovereign citizens as 'anti-government extremists' who believe they are separate or 'sovereign' from the United States. This designation highlighted the potential threat posed by the movement to law enforcement and public safety."
    },
    {
      "date": "2010s",
      "headline": "International Spread",
      "text": "Throughout the 2010s, the sovereign citizen movement continued to expand internationally, influencing similar groups in various countries. The movement's ideas were disseminated through the internet and social media, reaching a global audience."
    }
  ]
}

