    {
      "date": "-681",
      "headline": "Establishment of the First Bulgarian Empire",
      "text": "The First Bulgarian Empire was established in 681 AD after the Bulgars, led by Khan Asparuh, defeated the Byzantine Empire and secured the territory between the Danube and the Balkan Mountains."
    },
    {
      "date": "864",
      "headline": "Christianization of Bulgaria",
      "text": "Under the rule of Boris I, Bulgaria officially adopted Christianity as the state religion, which helped to unify the diverse population and strengthen ties with other Christian states."
    },
    {
      "date": "1018",
      "headline": "End of the First Bulgarian Empire",
      "text": "The First Bulgarian Empire came to an end when it was conquered by the Byzantine Empire under Emperor Basil II, also known as Basil the Bulgar Slayer."
    },
    {
      "date": "1185",
      "headline": "Establishment of the Second Bulgarian Empire",
      "text": "The Second Bulgarian Empire was established following a successful uprising led by the brothers Asen and Peter against Byzantine rule."
    },
    {
      "date": "1396",
      "headline": "Ottoman Conquest of Bulgaria",
      "text": "The Second Bulgarian Empire fell to the Ottoman Empire, leading to nearly five centuries of Ottoman rule over Bulgaria."
    },
    {
      "date": "1878",
      "headline": "Liberation of Bulgaria",
      "text": "Following the Russo-Turkish War (1877–1878), the Treaty of San Stefano was signed, leading to the liberation of Bulgaria from Ottoman rule and the establishment of an autonomous Bulgarian principality."
    },
    {
      "date": "1908",
      "headline": "Declaration of Independence",
      "text": "Bulgaria declared its full independence from the Ottoman Empire on September 22, 1908, and Ferdinand of Bulgaria was proclaimed Tsar."
    },
    {
      "date": "1946",
      "headline": "Establishment of the People's Republic of Bulgaria",
      "text": "Following a referendum, Bulgaria abolished the monarchy and established a people's republic, aligning itself with the Soviet Union during the Cold War."
    },
    {
      "date": "1989",
      "headline": "End of Communist Rule",
      "text": "The fall of communism in Bulgaria began with the resignation of Todor Zhivkov, leading to democratic reforms and the establishment of a multi-party system."
    },
    {
      "date": "2007",
      "headline": "Bulgaria Joins the European Union",
      "text": "On January 1, 2007, Bulgaria became a member of the European Union, marking a significant step in its integration into European political and economic structures."
    }
  ]
}

{
