      "date": "1496",
      "headline": "Founding of Santo Domingo",
      "text": "Bartholomew Columbus, brother of Christopher Columbus, establishes the city of Santo Domingo, which becomes the oldest continuously inhabited European settlement in the Americas."
    },
    {
      "date": "1697",
      "headline": "Treaty of Ryswick",
      "text": "The Treaty of Ryswick is signed, ending the Nine Years' War. Spain cedes the western third of Hispaniola to France, which later becomes Haiti."
    },
    {
      "date": "1821-12-01",
      "headline": "Independence from Spain",
      "text": "José Núñez de Cáceres declares the independence of the eastern part of Hispaniola from Spanish rule, naming it the Republic of Spanish Haiti."
    },
    {
      "date": "1822-02-09",
      "headline": "Unification with Haiti",
      "text": "The newly independent eastern part of Hispaniola is unified with Haiti under the leadership of Haitian President Jean-Pierre Boyer."
    },
    {
      "date": "1844-02-27",
      "headline": "Dominican War of Independence",
      "text": "The Dominican Republic declares independence from Haiti, led by Juan Pablo Duarte and the Trinitarians, establishing the Dominican Republic as a sovereign nation."
    },
    {
      "date": "1861-03-18",
      "headline": "Annexation by Spain",
      "text": "President Pedro Santana signs a pact with Spain, leading to the annexation of the Dominican Republic back to Spanish rule."
    },
    {
      "date": "1865-03-03",
      "headline": "Restoration of Independence",
      "text": "The Dominican Republic regains its independence from Spain after the War of Restoration, ending Spanish colonial rule."
    },
    {
      "date": "1916-05-16",
      "headline": "U.S. Occupation",
      "text": "The United States begins an occupation of the Dominican Republic, which lasts until 1924, to stabilize the region and protect American interests."
    },
    {
      "date": "1930-08-16",
      "headline": "Rafael Trujillo's Rise to Power",
      "text": "Rafael Trujillo becomes the President of the Dominican Republic, beginning a dictatorship that lasts until his assassination in 1961."
    },
    {
      "date": "1961-05-30",
      "headline": "Assassination of Rafael Trujillo",
      "text": "Rafael Trujillo is assassinated, ending his 31-year dictatorship and leading to a period of political instability."
    },
    {
      "date": "1965-04-24",
      "headline": "Dominican Civil War",
      "text": "A civil war breaks out following a military coup, leading to U.S. intervention to prevent the establishment of a communist government."
    },
    {
      "date": "1966-06-01",
      "headline": "Election of Joaquín Balaguer",
      "text": "Joaquín Balaguer is elected President, beginning a period of authoritarian rule that lasts until 1978, with subsequent terms in the 1980s and 1990s."
    },
    {
