      "headline": "Murder of XXXTentacion",
      "text": "On June 18, 2018, 20-year-old American rapper and singer-songwriter Jahseh Dwayne Ricardo Onfroy, known professionally as XXXTentacion, was murdered in Deerfield Beach, Florida. He was fatally shot by 22-year-old Michael Boatwright after being robbed in his car by Boatwright and his accomplices Trayvon Newsome, Dedrick Williams, and Robert Allen outside RIVA Motorsports."
    },
    {
      "date": "2018-06-20",
      "headline": "Arrest of Dedrick Williams",
      "text": "Dedrick Williams was arrested two days after the murder of XXXTentacion and charged with first-degree murder and robbery with a firearm."
    },
    {
      "date": "2018-07-05",
      "headline": "Arrest of Michael Boatwright",
      "text": "Michael Boatwright was arrested and charged with first-degree murder in connection with the murder of XXXTentacion."
    },
    {
      "date": "2018-07-25",
      "headline": "Arrest of Robert Allen",
      "text": "Robert Allen was arrested in Georgia and charged with first-degree murder and robbery with a firearm for his involvement in the murder of XXXTentacion."
    },
    {
      "date": "2018-08-07",
      "headline": "Arrest of Trayvon Newsome",
      "text": "Trayvon Newsome, the fourth suspect, was arrested and charged with first-degree murder and robbery with a firearm."
    }
  ]
}

{
  "timeline": [
    {
      "date": "1953",
      "headline": "Project MKUltra Begins",
      "text": "The CIA officially launches Project MKUltra, a covert program aimed at developing mind control techniques through the use of drugs and psychological manipulation."
    },
    {
      "date": "1953-04-13",
      "headline": "Approval by CIA Director",
      "text": "CIA Director Allen Dulles approves the MKUltra project, providing the program with a substantial budget and the authority to conduct experiments."
    },
    {
      "date": "1953-11",
      "headline": "Death of Frank Olson",
      "text": "Frank Olson, a scientist working with the CIA, dies under suspicious circumstances after being unwittingly dosed with LSD as part of MKUltra experiments."
    },
    {
      "date": "1955",
      "headline": "Expansion of Experiments",
      "text": "The scope of MKUltra expands to include experiments on hypnosis, sensory deprivation, and the effects of various drugs, including LSD, on human subjects."
    },
    {
      "date": "1964",
      "headline": "Project MKUltra Renamed",
      "text": "The project is renamed MKSEARCH, continuing the research into mind control techniques with a focus on behavioral modification."
    },
    {
      "date": "1973",
      "headline": "Destruction of Records",
      "text": "CIA Director Richard Helms orders the destruction of all MKUltra records, aiming to eliminate evidence of the program's activities."
    },
    {
      "date": "1975",
      "headline": "Church Committee Investigation",
      "text": "The U.S. Senate's Church Committee investigates MKUltra, revealing the program's unethical experiments on unwitting subjects."
    },
    {
      "date": "1977",
      "headline": "Freedom of Information Act Release",
      "text": "Documents related to MKUltra are released under the Freedom of Information Act, providing further details about the program's scope and methods."
    },
    {
      "date": "1977-08-03",
      "headline": "Senate Hearings on MKUltra",
      "text": "The U.S. Senate holds hearings on MKUltra, where former CIA officials testify about the program's activities and objectives."
    },
    {
      "date": "1995",
      "headline": "Presidential Apology",
      "text": "President Bill Clinton issues a formal apology to victims of MKUltra and other unethical government experiments, acknowledging the harm caused."
    }
  ]
}

