{
  "timeline": [
    {
      "date": "1999",
      "headline": "Introduction of the Dunning–Kruger Effect",
      "text": "The Dunning–Kruger effect was first described by psychologists David Dunning and Justin Kruger in a paper published in the Journal of Personality and Social Psychology. The paper, titled 'Unskilled and Unaware of It: How Difficulties in Recognizing One's Own Incompetence Lead to Inflated Self-Assessments,' outlined the cognitive bias where individuals with low ability at a task overestimate their ability."
    },
    {
      "date": "2000",
      "headline": "Ig Nobel Prize",
      "text": "David Dunning and Justin Kruger were awarded the Ig Nobel Prize in Psychology for their work on the Dunning–Kruger effect. The Ig Nobel Prizes are a parody of the Nobel Prizes and are awarded for unusual or trivial achievements in scientific research."
    },
    {
      "date": "2003",
      "headline": "Further Research and Expansion",
      "text": "Further studies and research expanded on the Dunning–Kruger effect, exploring its implications in various fields such as education, business, and medicine. Researchers began to investigate how the effect influences decision-making and self-assessment in different contexts."
    },
    {
      "date": "2011",
      "headline": "Book Publication",
      "text": "David Dunning published a book titled 'Self-Insight: Roadblocks and Detours on the Path to Knowing Thyself,' which delves into the Dunning–Kruger effect and other psychological phenomena related to self-awareness and self-assessment."
    },
    {
      "date": "2018",
      "headline": "Wider Recognition and Misinterpretations",
      "text": "The Dunning–Kruger effect gained wider recognition in popular culture, often being misinterpreted as a general statement about overconfidence in people with low intelligence, rather than the specific overconfidence of individuals unskilled at a particular task."
    }
  ]
}

