{
  "timeline": [
    {
      "date": "1832",
      "headline": "Coining of the Term 'Teetotalism'",
      "text": "The term 'teetotalism' is believed to have been coined in 1832 by Richard Turner, a member of the Preston Temperance Society in England. It was used to emphasize total abstinence from alcoholic beverages."
    },
    {
      "date": "1833",
      "headline": "Formation of the British Association for the Promotion of Temperance",
      "text": "In 1833, the British Association for the Promotion of Temperance was formed, which later became known as the British Temperance League. It played a significant role in promoting teetotalism in the UK."
    },
    {
      "date": "1838",
      "headline": "Establishment of the American Temperance Union",
      "text": "The American Temperance Union was established in 1838, promoting teetotalism and advocating for the prohibition of alcohol in the United States."
    },
    {
      "date": "1847",
      "headline": "Foundation of the Band of Hope",
      "text": "The Band of Hope was founded in 1847 in Leeds, England, to teach children the importance and benefits of teetotalism and to encourage them to pledge lifelong abstinence from alcohol."
    },
    {
      "date": "1851",
      "headline": "Maine Law Enacted",
      "text": "In 1851, Maine became the first U.S. state to enact a law prohibiting the sale of alcoholic beverages, influenced by the temperance movement and teetotalism advocacy."
    },
    {
      "date": "1873",
      "headline": "Women's Christian Temperance Union Founded",
      "text": "The Women's Christian Temperance Union (WCTU) was founded in 1873 in Ohio, USA. It became one of the largest and most influential groups advocating for teetotalism and the prohibition of alcohol."
    },
    {
      "date": "1893",
      "headline": "Anti-Saloon League Established",
      "text": "The Anti-Saloon League was established in 1893 in Ohio, USA. It became a powerful political force in the early 20th century, advocating for prohibition and teetotalism."
    },
    {
      "date": "1920-01-17",
      "headline": "Prohibition Begins in the United States",
      "text": "The 18th Amendment to the United States Constitution went into effect on January 17, 1920, marking the beginning of Prohibition, a nationwide ban on the production, importation, transportation, and sale of alcoholic beverages."
    },
    {
      "date": "1933-12-05",
      "headline": "End of Prohibition in the United States",
      "text": "The 21st Amendment to the United States Constitution was ratified on December 5, 1933, repealing the 18th Amendment and ending Prohibition in the United States."
    }
  ]
}

