    {
      "date": "0742",
      "headline": "Birth of Charlemagne",
      "text": "Charlemagne, also known as Charles the Great, was born in 742. The exact date and place of his birth are uncertain, but he was the eldest son of Pepin the Short and Bertrada of Laon."
    },
    {
      "date": "0768",
      "headline": "Became King of the Franks",
      "text": "Charlemagne became King of the Franks in 768 following the death of his father, Pepin the Short. He initially co-ruled with his brother Carloman I."
    },
    {
      "date": "0771",
      "headline": "Sole Ruler of the Franks",
      "text": "After the death of his brother Carloman I in 771, Charlemagne became the sole ruler of the Frankish Kingdom."
    },
    {
      "date": "0774",
      "headline": "Conquest of the Lombards",
      "text": "Charlemagne conquered the Lombard Kingdom in 774, becoming King of the Lombards and solidifying his power in Italy."
    },
    {
      "date": "0782",
      "headline": "Massacre of Verden",
      "text": "Charlemagne ordered the execution of 4,500 Saxons at Verden in 782, as part of his campaign to subdue and convert the Saxons."
    },
    {
      "date": "0796",
      "headline": "Annexation of Bavaria",
      "text": "Charlemagne annexed Bavaria in 796, further expanding his empire and consolidating his control over Central Europe."
    },
    {
      "date": "0800-12-25",
      "headline": "Crowned Emperor of the Romans",
      "text": "On Christmas Day in 800, Charlemagne was crowned Emperor of the Romans by Pope Leo III in St. Peter's Basilica, Rome, marking the revival of the Western Roman Empire."
    },
    {
      "date": "0804",
      "headline": "Completion of the Saxon Wars",
      "text": "Charlemagne completed the Saxon Wars in 804, successfully converting the Saxons to Christianity and integrating their territory into his empire."
    },
    {
      "date": "0814-01-28",
      "headline": "Death of Charlemagne",
      "text": "Charlemagne died on January 28, 814, in Aachen, the capital of his empire. He was buried in the Aachen Cathedral, leaving behind a legacy that shaped medieval Europe."
    }
  ]
}

