      "date": "1989-04-15",
      "headline": "Beginning of Protests",
      "text": "The Tiananmen Square protests began following the death of Hu Yaobang, a former Communist Party leader who had become a symbol of reform. Students gathered in Tiananmen Square to mourn his death and call for political reform."
    },
    {
      "date": "1989-04-18",
      "headline": "Student March",
      "text": "Students marched to Tiananmen Square to present a petition to the government, demanding democratic reforms and an end to corruption."
    },
    {
      "date": "1989-04-26",
      "headline": "People's Daily Editorial",
      "text": "The Chinese government published an editorial in the People's Daily, labeling the protests as 'turmoil' and warning of severe consequences, which further inflamed the protests."
    },
    {
      "date": "1989-05-13",
      "headline": "Hunger Strike Begins",
      "text": "In an effort to gain public sympathy and force the government to engage in dialogue, students began a hunger strike in Tiananmen Square."
    },
    {
      "date": "1989-05-15",
      "headline": "Gorbachev's Visit",
      "text": "Soviet leader Mikhail Gorbachev visited Beijing, drawing international media attention to the protests, as the hunger strike continued."
    },
    {
      "date": "1989-05-19",
      "headline": "Martial Law Declared",
      "text": "Premier Li Peng declared martial law in parts of Beijing, but the initial attempt to enforce it was met with resistance from citizens and local officials."
    },
    {
      "date": "1989-06-03",
      "headline": "Troops Enter Beijing",
      "text": "The Chinese government ordered the military to move into Beijing to suppress the protests. Clashes between troops and civilians began as the army approached Tiananmen Square."
    },
    {
      "date": "1989-06-04",
      "headline": "Tiananmen Square Massacre",
      "text": "In the early hours of June 4, troops and tanks cleared Tiananmen Square, using live ammunition against civilians. The exact number of casualties remains unknown, but estimates range from hundreds to thousands."
    },
    {
      "date": "1989-06-05",
      "headline": "Tank Man",
      "text": "A lone protester, known as 'Tank Man,' stood in front of a column of tanks leaving Tiananmen Square, becoming an iconic image of resistance."
    }
  ]
}

