      "date": "-0600",
      "headline": "Early Human Settlement",
      "text": "Archaeological evidence suggests that humans have been living in Papua New Guinea for tens of thousands of years, with the earliest settlers arriving around 60,000 years ago."
    },
    {
      "date": "1526",
      "headline": "First European Contact",
      "text": "Portuguese explorer Jorge de Meneses is believed to be the first European to sight Papua New Guinea, naming it 'Ilhas dos Papuas'."
    },
    {
      "date": "1545",
      "headline": "Naming of New Guinea",
      "text": "Spanish explorer Íñigo Ortiz de Retes names the island 'Nueva Guinea' due to the resemblance of the indigenous people to those found on the African Guinea coast."
    },
    {
      "date": "1884",
      "headline": "Colonial Division",
      "text": "The island of New Guinea is divided between Germany and the United Kingdom, with the northern part becoming German New Guinea and the southern part becoming British New Guinea."
    },
    {
      "date": "1906",
      "headline": "Transfer to Australia",
      "text": "British New Guinea is transferred to Australian administration and renamed the Territory of Papua."
    },
    {
      "date": "1914",
      "headline": "Australian Occupation",
      "text": "During World War I, Australian forces occupy German New Guinea, which is later mandated to Australia by the League of Nations."
    },
    {
      "date": "1942",
      "headline": "World War II Impact",
      "text": "Papua New Guinea becomes a major battleground during World War II, with significant battles such as the Kokoda Track campaign."
    },
    {
      "date": "1949",
      "headline": "Territorial Unification",
      "text": "The territories of Papua and New Guinea are administratively united under Australian administration as the Territory of Papua and New Guinea."
    },
    {
      "date": "1971",
      "headline": "Name Change",
      "text": "The name of the territory is changed to Papua New Guinea."
    },
    {
      "date": "1975-09-16",
      "headline": "Independence",
      "text": "Papua New Guinea gains independence from Australia, becoming a sovereign nation with Michael Somare as its first Prime Minister."
    },
    {
      "date": "1988",
      "headline": "Bougainville Conflict",
      "text": "A civil conflict begins on the island of Bougainville, leading to a decade-long struggle for independence from Papua New Guinea."
    },
    {
      "date": "2001",
      "headline": "Bougainville Peace Agreement",
      "text": "A peace agreement is signed, granting Bougainville autonomy and the promise of a future referendum on independence."
    },
    {
      "date": "2019",
      "headline": "Bougainville Referendum",
      "text": "A non-binding independence referendum is held in Bougainville, with an overwhelming majority voting in favor of independence from Papua New Guinea."
    }
  ]
}

