    {
      "date": "1792",
      "headline": "Coinage Act of 1792",
      "text": "The United States Congress passed the Coinage Act of 1792, which established the U.S. dollar as the country's standard unit of money. The Act created the U.S. Mint and authorized the minting of coins denominated in dollars and cents."
    },
    {
      "date": "1861",
      "headline": "Introduction of Demand Notes",
      "text": "During the American Civil War, the U.S. government issued Demand Notes, the first paper currency issued by the United States Treasury, to finance the war effort."
    },
    {
      "date": "1862",
      "headline": "Introduction of Legal Tender Notes",
      "text": "The United States began issuing Legal Tender Notes, also known as 'greenbacks,' which were the first widely circulated paper currency in the U.S. that was not backed by gold or silver."
    },
    {
      "date": "1913",
      "headline": "Federal Reserve Act",
      "text": "The Federal Reserve Act was signed into law, establishing the Federal Reserve System as the central bank of the United States, which was given the authority to issue Federal Reserve Notes as the new form of U.S. currency."
    },
    {
      "date": "1933",
      "headline": "Gold Standard Abandoned",
      "text": "President Franklin D. Roosevelt took the United States off the gold standard, prohibiting the private ownership of gold and requiring citizens to exchange gold coins, gold bullion, and gold certificates for U.S. dollars."
    },
    {
      "date": "1971",
      "headline": "Nixon Ends Bretton Woods System",
      "text": "President Richard Nixon announced the suspension of the U.S. dollar's convertibility into gold, effectively ending the Bretton Woods system and allowing the dollar to float freely in foreign exchange markets."
    },
    {
      "date": "1996",
      "headline": "Introduction of Redesigned U.S. Banknotes",
      "text": "The U.S. Treasury began issuing a series of redesigned banknotes with enhanced security features to combat counterfeiting, starting with the $100 bill."
    }
  ]
}

