      "date": "1806",
      "headline": "Sovereignty Recognized",
      "text": "Liechtenstein became a sovereign state when the Holy Roman Empire was dissolved. It joined the Confederation of the Rhine under the protection of Napoleon."
    },
    {
      "date": "1815",
      "headline": "German Confederation Membership",
      "text": "Liechtenstein became a member of the German Confederation, a loose association of Central European states created by the Congress of Vienna."
    },
    {
      "date": "1866",
      "headline": "Austro-Prussian War",
      "text": "Liechtenstein remained neutral during the Austro-Prussian War. After the dissolution of the German Confederation, Liechtenstein became fully independent."
    },
    {
      "date": "1868",
      "headline": "Abolition of the Army",
      "text": "Liechtenstein abolished its army due to financial constraints and has remained without a military since then."
    },
    {
      "date": "1921",
      "headline": "New Constitution",
      "text": "A new constitution was adopted, establishing Liechtenstein as a constitutional monarchy with a parliamentary system."
    },
    {
      "date": "1924",
      "headline": "Customs Union with Switzerland",
      "text": "Liechtenstein entered into a customs union with Switzerland, aligning its economic policies closely with its neighbor."
    },
    {
      "date": "1938",
      "headline": "Prince Franz Joseph II",
      "text": "Prince Franz Joseph II became the reigning prince, marking the first time a prince of Liechtenstein took up permanent residence in the country."
    },
    {
      "date": "1990",
      "headline": "United Nations Membership",
      "text": "Liechtenstein joined the United Nations, further establishing its presence in international affairs."
    },
    {
      "date": "1995",
      "headline": "European Economic Area",
      "text": "Liechtenstein became a member of the European Economic Area, allowing it to participate in the European single market without being a member of the European Union."
    },
    {
      "date": "2004",
      "headline": "Hans-Adam II Transfers Power",
      "text": "Prince Hans-Adam II transferred the day-to-day powers of the monarchy to his son, Hereditary Prince Alois, while retaining the title of reigning prince."
    }
  ]
}

