      "date": "1431",
      "headline": "Birth of Vlad III",
      "text": "Vlad III, later known as Vlad the Impaler, was born in 1431 in Sighișoara, Transylvania, which was part of the Kingdom of Hungary at the time."
    },
    {
      "date": "1448",
      "headline": "First Reign as Voivode of Wallachia",
      "text": "Vlad III first became Voivode of Wallachia in 1448, but his reign was short-lived due to political instability and he was deposed within a few months."
    },
    {
      "date": "1456",
      "headline": "Second Reign Begins",
      "text": "Vlad III regained the throne of Wallachia in 1456, marking the beginning of his most significant and infamous period of rule."
    },
    {
      "date": "1459",
      "headline": "Mass Impalement of Saxons",
      "text": "In 1459, Vlad III ordered the impalement of Saxon merchants from Brașov, who had supported his rivals, as a demonstration of his power and as retribution for their betrayal."
    },
    {
      "date": "1460",
      "headline": "Conflict with the Ottoman Empire",
      "text": "Vlad III refused to pay tribute to the Ottoman Empire, leading to increased tensions and eventual military conflict."
    },
    {
      "date": "1462",
      "headline": "Night Attack at Târgoviște",
      "text": "In June 1462, Vlad III launched a surprise night attack on the Ottoman forces led by Sultan Mehmed II, which became one of his most famous military exploits."
    },
    {
      "date": "1462",
      "headline": "Capture and Imprisonment",
      "text": "Later in 1462, Vlad III was captured by Hungarian forces and imprisoned by Matthias Corvinus, King of Hungary, due to political machinations and accusations of treachery."
    },
    {
      "date": "1475",
      "headline": "Release and Third Reign",
      "text": "Vlad III was released from captivity in 1475 and briefly regained the throne of Wallachia in 1476 with the support of Hungarian and Moldavian forces."
    },
    {
      "date": "1476",
      "headline": "Death of Vlad III",
      "text": "Vlad III died in battle against the Ottoman-backed forces in late 1476 or early 1477. His exact date of death and the location of his burial remain uncertain."
    }
  ]
}

