      "date": "1830-08-18",
      "headline": "Birth of Franz Joseph I",
      "text": "Franz Joseph I was born in the Schönbrunn Palace in Vienna, Austria, to Archduke Franz Karl of Austria and Princess Sophie of Bavaria."
    },
    {
      "date": "1848-12-02",
      "headline": "Ascension to the Throne",
      "text": "Franz Joseph I became Emperor of Austria following the abdication of his uncle, Emperor Ferdinand I, during the Revolutions of 1848."
    },
    {
      "date": "1850-05-01",
      "headline": "President of the German Confederation",
      "text": "Franz Joseph I became the President of the German Confederation, a position he held until 1866."
    },
    {
      "date": "1854-04-24",
      "headline": "Marriage to Elisabeth of Bavaria",
      "text": "Franz Joseph I married his cousin, Elisabeth of Bavaria, who became known as Empress Elisabeth or 'Sisi'."
    },
    {
      "date": "1866-08-23",
      "headline": "Austro-Prussian War Ends",
      "text": "The Austro-Prussian War ended with the Treaty of Prague, resulting in Austria's exclusion from German affairs and the dissolution of the German Confederation."
    },
    {
      "date": "1867",
      "headline": "Austro-Hungarian Compromise",
      "text": "The Austro-Hungarian Compromise of 1867 established the dual monarchy of Austria-Hungary, with Franz Joseph I as both Emperor of Austria and King of Hungary."
    },
    {
      "date": "1889-01-30",
      "headline": "Death of Crown Prince Rudolf",
      "text": "Crown Prince Rudolf, the only son of Franz Joseph I, died in a murder-suicide at Mayerling, a significant personal and dynastic tragedy."
    },
    {
      "date": "1898-09-10",
      "headline": "Assassination of Empress Elisabeth",
      "text": "Empress Elisabeth, wife of Franz Joseph I, was assassinated by an Italian anarchist, Luigi Lucheni, in Geneva, Switzerland."
    },
    {
      "date": "1914-06-28",
      "headline": "Assassination of Archduke Franz Ferdinand",
      "text": "Archduke Franz Ferdinand, heir presumptive to the Austro-Hungarian throne, was assassinated in Sarajevo, an event that precipitated World War I."
    },
    {
      "date": "1916-11-21",
      "headline": "Death of Franz Joseph I",
      "text": "Franz Joseph I died at the age of 86 in the Schönbrunn Palace in Vienna, after a reign of 68 years, one of the longest in European history."
    }
  ]
}

