    {
      "date": "1672-04",
      "headline": "Franco-Dutch War",
      "text": "Louis XIV initiated the Franco-Dutch War to expand French territory and weaken the Dutch Republic."
    },
    {
      "date": "1682",
      "headline": "Court Moves to Versailles",
      "text": "Louis XIV officially moved his court and government to the Palace of Versailles, which became a symbol of his absolute power and the center of political life in France."
    },
    {
      "date": "1685-10-18",
      "headline": "Revocation of the Edict of Nantes",
      "text": "Louis XIV revoked the Edict of Nantes, which had granted religious freedom to Protestants in France, leading to the persecution of Huguenots."
    },
    {
      "date": "1701-07-09",
      "headline": "War of the Spanish Succession",
      "text": "The War of the Spanish Succession began, as European powers opposed the potential unification of the French and Spanish thrones under Louis XIV's grandson, Philip V of Spain."
    },
    {
