{
  "timeline": [
    {
      "date": "1944",
      "headline": "Initial Description by Hans Asperger",
      "text": "Austrian pediatrician Hans Asperger first described the condition in 1944, observing children in his practice who had difficulty with social interactions and exhibited restricted and repetitive behaviors."
    },
    {
      "date": "1981",
      "headline": "Term 'Asperger's Syndrome' Coined",
      "text": "The term 'Asperger's Syndrome' was coined by British psychiatrist Lorna Wing in a 1981 paper, bringing attention to Hans Asperger's earlier work and describing a similar pattern of behavior."
    },
    {
      "date": "1994",
      "headline": "Inclusion in DSM-IV",
      "text": "Asperger's Syndrome was included as a distinct diagnosis in the Diagnostic and Statistical Manual of Mental Disorders, Fourth Edition (DSM-IV), published by the American Psychiatric Association."
    },
    {
      "date": "2013",
      "headline": "Removal from DSM-5",
      "text": "The American Psychiatric Association removed Asperger's Syndrome as a separate diagnosis in the DSM-5, published in 2013, and incorporated it under the umbrella of Autism Spectrum Disorder (ASD)."
    },
    {
      "date": "2022",
      "headline": "ICD-11 Implementation",
      "text": "The World Health Organization's International Classification of Diseases, 11th Revision (ICD-11), which no longer lists Asperger's Syndrome as a separate diagnosis, came into effect in 2022. It is now part of Autism Spectrum Disorder."
    }
  ]
}

