      "date": "1960",
      "headline": "Synthesis of Fentanyl",
      "text": "Fentanyl was first synthesized by Dr. Paul Janssen in 1960. It was developed as part of a series of synthetic opioids aimed at improving the efficacy and safety of pain management."
    },
    {
      "date": "1968",
      "headline": "Introduction of Sublimaze",
      "text": "Fentanyl was introduced as an intravenous anesthetic under the brand name Sublimaze. It was primarily used in medical settings for pain management during surgery."
    },
    {
      "date": "1990",
      "headline": "Approval of Duragesic",
      "text": "The FDA approved the Duragesic patch, a transdermal system for delivering fentanyl, providing continuous pain relief for patients with chronic pain, particularly cancer patients."
    },
    {
      "date": "1998",
      "headline": "Introduction of Actiq",
      "text": "Actiq, a fentanyl lollipop, was approved for breakthrough cancer pain. It allowed for rapid absorption of fentanyl through the oral mucosa."
    },
    {
      "date": "2000s",
      "headline": "Rise in Illicit Use",
      "text": "Fentanyl began to appear more frequently in the illicit drug market, often mixed with or sold as heroin, leading to a significant increase in overdose deaths."
    },
    {
      "date": "2010s",
      "headline": "Fentanyl Crisis",
      "text": "The opioid crisis intensified with fentanyl being a major contributor to the rise in opioid-related overdose deaths in the United States and other countries."
    },
    {
      "date": "2016",
      "headline": "DEA Scheduling",
      "text": "The U.S. Drug Enforcement Administration (DEA) placed all fentanyl-related substances into Schedule I, indicating a high potential for abuse and no accepted medical use."
    },
    {
      "date": "2020",
      "headline": "Continued Impact",
      "text": "Fentanyl remained a leading cause of overdose deaths, with synthetic opioids, primarily fentanyl, involved in nearly 73% of all opioid-related deaths in the United States."
    }
  ]
}

