    },
    {
      "date": "-1755",
      "headline": "Code of Hammurabi",
      "text": "Hammurabi promulgated one of the earliest and most complete written legal codes, known as the Code of Hammurabi, which became a model for future legal systems."
    },
    {
      "date": "-1595",
      "headline": "Fall of the First Babylonian Dynasty",
      "text": "The Hittites, under King Mursili I, sacked Babylon, leading to the collapse of the First Babylonian Dynasty."
    },
    {
      "date": "-626",
      "headline": "Rise of the Neo-Babylonian Empire",
      "text": "Nabopolassar established the Neo-Babylonian Empire, marking a resurgence of Babylonian power in the region."
    },
    {
      "date": "-605",
