{
  "timeline": [
    {
      "date": "-0700",
      "headline": "Earliest Evidence of Tuberculosis",
      "text": "The earliest evidence of tuberculosis in humans has been found in the remains of a 9,000-year-old Neolithic settlement in the Eastern Mediterranean."
    },
    {
      "date": "0188",
      "headline": "Hippocrates Describes Tuberculosis",
      "text": "Hippocrates, the ancient Greek physician, described a disease with symptoms similar to tuberculosis, calling it 'phthisis'."
    },
    {
      "date": "0167",
      "headline": "Aretaeus of Cappadocia's Description",
      "text": "Aretaeus of Cappadocia provided a detailed description of tuberculosis, referring to it as 'consumption' due to the way it consumed the body."
    },
    {
      "date": "1025",
      "headline": "Avicenna's Canon of Medicine",
      "text": "Persian physician Avicenna included tuberculosis in his medical encyclopedia, 'The Canon of Medicine', describing its contagious nature."
    },
    {
      "date": "1720",
      "headline": "Benjamin Marten's Hypothesis",
      "text": "Benjamin Marten, an English physician, suggested that tuberculosis might be caused by 'minute living creatures'."
    },
    {
      "date": "1882-03-24",
      "headline": "Discovery of Mycobacterium tuberculosis",
      "text": "Robert Koch announced the discovery of Mycobacterium tuberculosis, the bacterium that causes tuberculosis, marking a significant breakthrough in understanding the disease."
    },
    {
      "date": "1921",
      "headline": "Development of BCG Vaccine",
      "text": "The Bacillus Calmette-Guérin (BCG) vaccine was developed by Albert Calmette and Camille Guérin as a preventive measure against tuberculosis."
    },
    {
      "date": "1943",
      "headline": "Discovery of Streptomycin",
      "text": "Selman Waksman and his team discovered streptomycin, the first effective antibiotic treatment for tuberculosis."
    },
    {
      "date": "1993",
      "headline": "WHO Declares TB a Global Emergency",
      "text": "The World Health Organization declared tuberculosis a global health emergency due to its widespread impact and rising incidence."
    },
    {
      "date": "2014",
      "headline": "Introduction of New TB Drugs",
      "text": "The introduction of new drugs, bedaquiline and delamanid, marked significant progress in the treatment of multidrug-resistant tuberculosis."
    }
  ]
}

