{
  "timeline": [
    {
      "date": "1865",
      "headline": "End of the Civil War",
      "text": "The American Civil War ended, leading to the abolition of slavery and the beginning of the Reconstruction era, during which African Americans made significant political and economic gains."
    },
    {
      "date": "1877",
      "headline": "End of Reconstruction",
      "text": "The Compromise of 1877 resulted in the withdrawal of federal troops from the South, marking the end of the Reconstruction era and leading to the rise of white-dominated state legislatures."
    },
    {
      "date": "1890",
      "headline": "Mississippi Plan",
      "text": "Mississippi adopted a new constitution that effectively disenfranchised African Americans through poll taxes, literacy tests, and understanding clauses."
    },
    {
      "date": "1896",
      "headline": "Plessy v. Ferguson",
      "text": "The U.S. Supreme Court upheld the constitutionality of racial segregation under the 'separate but equal' doctrine, providing legal justification for Jim Crow laws."
    },
    {
      "date": "1901",
      "headline": "Alabama Constitution",
      "text": "Alabama adopted a new constitution that included provisions to disenfranchise African Americans and poor whites through literacy tests and poll taxes."
    },
    {
      "date": "1915",
      "headline": "Guinn v. United States",
      "text": "The U.S. Supreme Court struck down grandfather clauses in Oklahoma and Maryland, which had exempted white voters from literacy tests."
    },
    {
      "date": "1948",
      "headline": "Executive Order 9981",
      "text": "President Harry S. Truman issued Executive Order 9981, desegregating the armed forces and marking a significant step towards civil rights."
    },
    {
      "date": "1954",
      "headline": "Brown v. Board of Education",
      "text": "The U.S. Supreme Court ruled that racial segregation in public schools was unconstitutional, overturning the 'separate but equal' doctrine established by Plessy v. Ferguson."
    },
    {
      "date": "1964",
      "headline": "Civil Rights Act of 1964",
      "text": "The Civil Rights Act was signed into law, prohibiting discrimination based on race, color, religion, sex, or national origin, and ending segregation in public places."
    },
    {
      "date": "1965",
      "headline": "Voting Rights Act of 1965",
      "text": "The Voting Rights Act was signed into law, prohibiting racial discrimination in voting and effectively ending the legal basis for Jim Crow laws."
    }
  ]
}

