{
  "timeline": [
    {
      "date": "-0230",
      "headline": "Mauryan Empire Rule",
      "text": "The region of Andhra Pradesh was part of the Mauryan Empire under Emperor Ashoka, who ruled from 268 to 232 BCE. The area was influenced by Buddhism during this period."
    },
    {
      "date": "0220",
      "headline": "Satavahana Dynasty",
      "text": "The Satavahana dynasty rose to power in the region, marking a significant period in Andhra Pradesh's history. They ruled for several centuries and were known for their contributions to art and architecture."
    },
    {
      "date": "1130",
      "headline": "Kakatiya Dynasty",
      "text": "The Kakatiya dynasty established its rule over the region, with Warangal as their capital. They were known for their patronage of Telugu literature and architecture."
    },
    {
      "date": "1323",
      "headline": "Delhi Sultanate Conquest",
      "text": "The region came under the control of the Delhi Sultanate after the fall of the Kakatiya dynasty."
    },
    {
      "date": "1518",
      "headline": "Vijayanagara Empire",
      "text": "The Vijayanagara Empire controlled the region, bringing prosperity and cultural development. The empire was known for its patronage of art and architecture."
    },
    {
      "date": "1687",
      "headline": "Mughal Empire Rule",
      "text": "The Mughal Empire annexed the region, incorporating it into their vast empire."
    },
    {
      "date": "1724",
      "headline": "Nizam of Hyderabad",
      "text": "The region became part of the Hyderabad State under the rule of the Nizam."
    },
    {
      "date": "1947",
      "headline": "Indian Independence",
      "text": "India gained independence from British rule, and Andhra Pradesh became part of the newly independent nation."
    },
    {
      "date": "1953-10-01",
      "headline": "Formation of Andhra State",
      "text": "Andhra State was formed from the Telugu-speaking northern districts of Madras State, with Kurnool as its capital."
    },
    {
      "date": "1956-11-01",
      "headline": "Formation of Andhra Pradesh",
      "text": "The state of Andhra Pradesh was formed by merging Andhra State with the Telugu-speaking areas of the Hyderabad State, with Hyderabad as the capital."
    },
    {
      "date": "2014-06-02",
      "headline": "Bifurcation of Andhra Pradesh",
      "text": "The state was bifurcated to form the new state of Telangana. Hyderabad became the joint capital of both states for a period of time."
    },
    {
      "date": "2015-04-01",
      "headline": "Amaravati as Capital",
      "text": "Amaravati was officially declared the new capital of Andhra Pradesh."
    }
  ]
}

{
  "timeline": [
    {
      "date": "-05000",
      "headline": "First Settlements",
      "text": "The first known settlements in Mesopotamia began around 5000 BCE, with the establishment of small agricultural communities."
    },
    {
      "date": "-03500",
      "headline": "Rise of Sumer",
      "text": "The Sumerians established one of the world's first civilizations in southern Mesopotamia, developing city-states such as Uruk, Ur, and Eridu."
    },
    {
      "date": "-03200",
      "headline": "Invention of Writing",
      "text": "The Sumerians developed cuneiform writing, one of the earliest known writing systems, around 3200 BCE."
    },
    {
      "date": "-02350",
      "headline": "Akkadian Empire",
      "text": "Sargon of Akkad founded the Akkadian Empire, unifying various city-states under his rule and creating one of the first empires in history."
    },
    {
      "date": "-02100",
      "headline": "Ur III Dynasty",
      "text": "The Third Dynasty of Ur, also known as the Neo-Sumerian Empire, saw a resurgence of Sumerian culture and power in Mesopotamia."
    },
    {
      "date": "-01750",
      "headline": "Hammurabi's Code",
      "text": "Hammurabi, the sixth king of the First Babylonian Dynasty, created one of the earliest and most complete written legal codes."
    },
    {
      "date": "-01590",
      "headline": "Kassite Dynasty",
      "text": "The Kassites took control of Babylon and ruled for several centuries, maintaining stability and cultural continuity."
    },
    {
      "date": "-0911",
      "headline": "Neo-Assyrian Empire",
      "text": "The Neo-Assyrian Empire emerged as a dominant power in Mesopotamia, known for its military prowess and extensive conquests."
    },
    {
      "date": "-0612",
      "headline": "Fall of Nineveh",
      "text": "The fall of Nineveh marked the end of the Neo-Assyrian Empire, as it was conquered by a coalition of Babylonians, Medes, and others."
    },
    {
      "date": "-0605",
      "headline": "Neo-Babylonian Empire",
      "text": "The Neo-Babylonian Empire, under rulers like Nebuchadnezzar II, became a major power, known for its architectural achievements such as the Hanging Gardens."
    },
    {
      "date": "-0539",
      "headline": "Persian Conquest",
      "text": "Cyrus the Great of Persia conquered Babylon, integrating Mesopotamia into the Achaemenid Empire."
    },
    {
      "date": "-0331",
      "headline": "Alexander the Great",
      "text": "Alexander the Great defeated the Persian Empire, bringing Mesopotamia under Greek influence."
    },
    {
      "date": "-0305",
      "headline": "Seleucid Empire",
      "text": "After Alexander's death, Mesopotamia became part of the Seleucid Empire, one of the Hellenistic successor states."
    },
    {
      "date": "-0141",
      "headline": "Parthian Control",
      "text": "The Parthian Empire gained control over Mesopotamia, marking a shift in power from Hellenistic to Iranian influence."
    },
    {
      "date": "0224",
      "headline": "Sassanian Empire",
      "text": "The Sassanian Empire succeeded the Parthians, ruling over Mesopotamia and revitalizing Persian culture and influence."
    },
    {
      "date": "0637",
      "headline": "Islamic Conquest",
      "text": "The Rashidun Caliphate conquered Mesopotamia, bringing the region under Islamic rule and marking the end of the Sassanian Empire."
    }
  ]
}

