    {
      "date": "1971-08",
      "headline": "Conception of the Libertarian Party",
      "text": "The Libertarian Party was conceived during meetings held in the home of David F. Nolan in Westminster, Colorado. The discussions were driven by concerns over the Nixon administration's policies, including wage and price controls, the Vietnam War, conscription, and the introduction of fiat money."
    },
    {
      "date": "1971-12-11",
      "headline": "Official Formation of the Libertarian Party",
      "text": "The Libertarian Party was officially formed in Colorado Springs, Colorado. The party was established as the first explicitly libertarian political party in the world, drawing inspiration from the works and ideas of Austrian school economist Murray Rothbard."
    },
    {
      "date": "1972",
      "headline": "First Libertarian Presidential Candidate",
      "text": "John Hospers became the first Libertarian presidential candidate. The Libertarian Party participated in the 1972 United States presidential election."
    },
    {
      "date": "1972",
      "headline": "First Electoral Vote",
      "text": "John Hospers received one electoral vote from a faithless elector in Virginia, becoming the first Libertarian presidential candidate to receive an electoral vote."
    },
    {
      "date": "1980",
      "headline": "Ed Clark's Presidential Campaign",
      "text": "Ed Clark ran as the Libertarian Party's presidential candidate, achieving the party's best result at the time with nearly 1% of the popular vote."
    },
    {
      "date": "1996",
      "headline": "Harry Browne's Presidential Campaign",
      "text": "Harry Browne ran as the Libertarian Party's presidential candidate, receiving over 485,000 votes, which was the highest number for a Libertarian candidate since 1980."
    },
    {
      "date": "2008",
      "headline": "Bob Barr's Presidential Campaign",
      "text": "Former Republican Congressman Bob Barr ran as the Libertarian Party's presidential candidate, receiving over 523,000 votes."
    },
    {
      "date": "2012",
      "headline": "Gary Johnson's Presidential Campaign",
      "text": "Former New Mexico Governor Gary Johnson ran as the Libertarian Party's presidential candidate, receiving over 1.2 million votes, the highest total for a Libertarian candidate at that time."
    },
    {
      "date": "2016",
      "headline": "Gary Johnson's Second Presidential Campaign",
      "text": "Gary Johnson ran again as the Libertarian Party's presidential candidate, receiving over 4.4 million votes, the highest number of votes ever received by a Libertarian candidate."
    },
    {
      "date": "2020",
      "headline": "Jo Jorgensen's Presidential Campaign",
      "text": "Jo Jorgensen ran as the Libertarian Party's presidential candidate, receiving over 1.8 million votes in the 2020 United States presidential election."
    }
  ]
}

