      "headline": "Schengen Agreement Signed",
      "text": "The Schengen Agreement was signed by five of the ten member states of the European Economic Community (EEC) in the village of Schengen, Luxembourg. The agreement aimed to gradually abolish border checks at the signatories' common borders."
    },
    {
      "date": "1990-06-19",
      "headline": "Schengen Convention Signed",
      "text": "The Schengen Convention was signed, supplementing the Schengen Agreement. It proposed the abolition of internal border controls and a common visa policy."
    },
    {
      "date": "1995-03-26",
      "headline": "Implementation of Schengen Agreement",
      "text": "The Schengen Agreement came into effect, initially involving seven countries: Belgium, France, Germany, Luxembourg, the Netherlands, Portugal, and Spain. Internal border checks were abolished among these countries."
    },
    {
      "date": "1997",
      "headline": "Incorporation into EU Law",
      "text": "The Treaty of Amsterdam incorporated the Schengen Agreements into the framework of the European Union, making them part of EU law."
    },
    {
      "date": "2001-03-25",
      "headline": "Nordic Countries Join",
      "text": "The Nordic countries, including Denmark, Finland, Iceland, Norway, and Sweden, joined the Schengen Area, further expanding the zone of free movement."
    },
    {
      "date": "2007-12-21",
      "headline": "Expansion to Eastern Europe",
      "text": "Nine new countries from Eastern Europe joined the Schengen Area: Czech Republic, Estonia, Hungary, Latvia, Lithuania, Malta, Poland, Slovakia, and Slovenia."
    },
    {
      "date": "2008-12-12",
      "headline": "Switzerland Joins Schengen Area",
      "text": "Switzerland became a member of the Schengen Area, allowing for the free movement of people across its borders with other Schengen countries."
    },
    {
      "date": "2011-12-19",
      "headline": "Liechtenstein Joins Schengen Area",
      "text": "Liechtenstein joined the Schengen Area, becoming the 26th country to participate in the agreement."
    },
    {
      "date": "2023",
      "headline": "Croatia Joins Schengen Area",
      "text": "Croatia became the latest country to join the Schengen Area, further expanding the zone of free movement within Europe."
    }
  ]
}

