{
  "timeline": [
    {
      "date": "1929-10-24",
      "headline": "Black Thursday",
      "text": "The Wall Street stock market crash begins on October 24, 1929, known as Black Thursday, marking the start of the Great Depression. Panic selling ensues, and the market loses 11% of its value at the opening bell."
    },
    {
      "date": "1929-10-29",
      "headline": "Black Tuesday",
      "text": "On October 29, 1929, known as Black Tuesday, the stock market crash reaches its peak with a record 16 million shares traded. The market loses billions of dollars, leading to widespread financial panic."
    },
    {
      "date": "1930",
      "headline": "Bank Failures Begin",
      "text": "In 1930, the first wave of bank failures occurs in the United States. Over 1,300 banks fail, leading to a loss of savings for many Americans and a further contraction of the economy."
    },
    {
      "date": "1930-06",
      "headline": "Smoot-Hawley Tariff Act",
      "text": "In June 1930, the United States enacts the Smoot-Hawley Tariff Act, raising tariffs on thousands of imported goods. This leads to a decrease in international trade and worsens the global economic situation."
    },
    {
      "date": "1931",
      "headline": "Global Spread of Depression",
      "text": "By 1931, the Great Depression spreads globally, affecting economies in Europe, Latin America, and Asia. Many countries experience severe economic downturns, high unemployment, and social unrest."
    },
    {
      "date": "1931-09",
      "headline": "British Gold Standard Abandonment",
      "text": "In September 1931, the United Kingdom abandons the gold standard, allowing the British pound to float freely. This decision helps stabilize the British economy but signals the deepening of the global economic crisis."
    },
    {
      "date": "1932",
      "headline": "Peak Unemployment in the U.S.",
      "text": "In 1932, unemployment in the United States reaches its peak at approximately 25%, with millions of Americans out of work and widespread poverty."
    },
    {
      "date": "1933-03-04",
      "headline": "Franklin D. Roosevelt Inauguration",
      "text": "On March 4, 1933, Franklin D. Roosevelt is inaugurated as the 32nd President of the United States. He introduces the New Deal, a series of programs and reforms aimed at economic recovery."
    },
    {
      "date": "1933-03-09",
      "headline": "Emergency Banking Act",
      "text": "On March 9, 1933, the U.S. Congress passes the Emergency Banking Act, allowing the government to stabilize the banking system and restore public confidence."
    },
    {
      "date": "1933-04",
      "headline": "U.S. Abandons Gold Standard",
      "text": "In April 1933, the United States abandons the gold standard, allowing the dollar to float and helping to stimulate economic recovery."
    },
    {
      "date": "1935",
      "headline": "Social Security Act",
      "text": "In 1935, the Social Security Act is signed into law in the United States, establishing a system of old-age benefits and unemployment insurance as part of the New Deal reforms."
    },
    {
      "date": "1936",
      "headline": "Economic Recovery Begins",
      "text": "By 1936, signs of economic recovery begin to appear in the United States and other countries, although unemployment remains high."
    },
    {
      "date": "1939",
      "headline": "End of the Great Depression",
      "text": "The Great Depression is generally considered to have ended by 1939, as global economies begin to recover and World War II leads to increased industrial production and employment."
    }
  ]
}

