{
  "timeline": [
    {
      "date": "-0753-04-21",
      "headline": "Founding of Rome",
      "text": "According to legend, Rome was founded on April 21, 753 BCE by Romulus and Remus, twin sons of Mars, the god of war."
    },
    {
      "date": "-0509",
      "headline": "Establishment of the Roman Republic",
      "text": "The Roman Kingdom was overthrown, and the Roman Republic was established, marking the beginning of a new era of Roman governance."
    },
    {
      "date": "-0275",
      "headline": "Rome's Dominance in Italy",
      "text": "By 275 BCE, Rome had established dominance over the Italian peninsula after defeating the Samnites and other tribes."
    },
    {
      "date": "-0146",
      "headline": "Destruction of Carthage",
      "text": "Rome destroyed Carthage in 146 BCE, ending the Third Punic War and establishing Roman dominance over the western Mediterranean."
    },
    {
      "date": "-0027",
      "headline": "Beginning of the Roman Empire",
      "text": "In 27 BCE, Augustus became the first Roman Emperor, marking the end of the Roman Republic and the beginning of the Roman Empire."
    },
    {
      "date": "0064",
      "headline": "Great Fire of Rome",
      "text": "A great fire ravaged Rome in 64 CE, destroying much of the city. Emperor Nero was rumored to have started the fire, although this is debated by historians."
    },
    {
      "date": "0313",
      "headline": "Edict of Milan",
      "text": "Emperor Constantine issued the Edict of Milan in 313 CE, granting religious tolerance for Christianity and ending persecution of Christians."
    },
    {
      "date": "0395",
      "headline": "Division of the Roman Empire",
      "text": "The Roman Empire was permanently divided into the Western Roman Empire and the Eastern Roman Empire (Byzantine Empire) in 395 CE."
    },
    {
      "date": "0455",
      "headline": "Sack of Rome by the Vandals",
      "text": "In 455 CE, the Vandals, led by King Genseric, sacked Rome, marking one of the significant events leading to the fall of the Western Roman Empire."
    },
    {
      "date": "0476",
      "headline": "Fall of the Western Roman Empire",
      "text": "The Western Roman Empire officially fell in 476 CE when the last Roman emperor, Romulus Augustulus, was deposed by the Germanic chieftain Odoacer."
    },
    {
      "date": "0752",
      "headline": "Establishment of the Papal States",
      "text": "The Papal States were established in 752 CE, with Rome as the center of papal authority and governance."
    },
    {
      "date": "1309",
      "headline": "Avignon Papacy",
      "text": "From 1309 to 1377, the papacy was based in Avignon, France, rather than Rome, due to political conflicts and pressures."
    },
    {
      "date": "1377",
      "headline": "Return of the Papacy to Rome",
      "text": "Pope Gregory XI returned the papacy to Rome in 1377, ending the Avignon Papacy and re-establishing Rome as the center of the Catholic Church."
    },
    {
      "date": "1870",
      "headline": "Capture of Rome",
      "text": "Rome was captured by the Kingdom of Italy in 1870, marking the end of the Papal States and the unification of Italy."
    },
    {
      "date": "1929",
      "headline": "Lateran Treaty",
      "text": "The Lateran Treaty was signed in 1929, establishing Vatican City as an independent state within Rome and resolving the 'Roman Question.'"
    },
    {
      "date": "1946",
      "headline": "Rome as Capital of the Italian Republic",
      "text": "Following World War II, Rome became the capital of the newly established Italian Republic in 1946."
    },
    {
      "date": "1960",
      "headline": "Rome Olympics",
      "text": "Rome hosted the Summer Olympics in 1960, showcasing the city on an international stage."
    }
  ]
}

{
