{
  "timeline": [
    {
      "date": "1920-04",
      "headline": "San Remo Conference",
      "text": "The San Remo Conference was held in April 1920, where the Allied Supreme Council decided to assign the mandate for Palestine to Britain, incorporating the Balfour Declaration which supported the establishment of a national home for the Jewish people in Palestine."
    },
    {
      "date": "1920-07",
      "headline": "British Military Administration",
      "text": "The British military administration in Palestine was replaced by a civil administration, marking the beginning of British governance in the region."
    },
    {
      "date": "1922-07-24",
      "headline": "League of Nations Mandate",
      "text": "The League of Nations formally approved the British Mandate for Palestine, which came into effect on September 29, 1923. The mandate included the Balfour Declaration and aimed to establish a Jewish national home while respecting the rights of existing non-Jewish communities."
    },
    {
      "date": "1929-08",
      "headline": "1929 Palestine Riots",
      "text": "A series of violent riots erupted in late August 1929, primarily in Jerusalem, Hebron, and Safed, resulting in the deaths of 133 Jews and 116 Arabs. The riots were fueled by tensions over Jewish access to the Western Wall and broader Arab-Jewish tensions."
    },
    {
      "date": "1936-04",
      "headline": "Arab Revolt",
      "text": "The Arab Revolt began in April 1936, lasting until 1939. It was a nationalist uprising by Palestinian Arabs against British colonial rule and mass Jewish immigration. The revolt included strikes, protests, and violent attacks."
    },
    {
      "date": "1937-07",
      "headline": "Peel Commission Report",
      "text": "The Peel Commission Report was published in July 1937, recommending the partition of Palestine into separate Jewish and Arab states. This was the first official proposal for partition, but it was rejected by Arab leaders and led to further tensions."
    },
    {
      "date": "1939-05",
      "headline": "White Paper of 1939",
      "text": "The British government issued the White Paper of 1939, which limited Jewish immigration to 75,000 over five years and restricted land sales to Jews. This policy aimed to appease Arab opposition but was opposed by Jewish leaders."
    },
    {
      "date": "1947-11-29",
      "headline": "UN Partition Plan",
      "text": "The United Nations General Assembly adopted Resolution 181, recommending the partition of Palestine into independent Arab and Jewish states and an international regime for Jerusalem. The plan was accepted by Jewish leaders but rejected by Arab leaders."
    },
    {
      "date": "1948-05-14",
      "headline": "End of British Mandate",
      "text": "The British Mandate for Palestine officially ended on May 14, 1948. On the same day, the State of Israel declared independence, leading to the 1948 Arab-Israeli War as neighboring Arab states invaded the former mandate territory."
    }
  ]
}

