      "date": "-0001",
      "headline": "Formation of the Kingdom of Rwanda",
      "text": "The Kingdom of Rwanda was established in the region, with the Tutsi monarchy ruling over the Hutu majority population. This kingdom laid the foundation for the modern state of Rwanda."
    },
    {
      "date": "1884",
      "headline": "Berlin Conference",
      "text": "The Berlin Conference resulted in the partitioning of Africa among European powers. Rwanda, along with Burundi, was assigned to Germany as part of German East Africa."
    },
    {
      "date": "1916",
      "headline": "Belgian Occupation",
      "text": "During World War I, Belgian forces from the Congo occupied Rwanda, taking control from the Germans."
    },
    {
      "date": "1923",
      "headline": "League of Nations Mandate",
      "text": "The League of Nations granted Belgium a mandate to govern Rwanda and Burundi, known as Ruanda-Urundi."
    },
    {
      "date": "1962-07-01",
      "headline": "Independence from Belgium",
      "text": "Rwanda gained independence from Belgium, becoming a republic. The monarchy was abolished, and Grégoire Kayibanda became the first President of Rwanda."
    },
    {
      "date": "1973-07-05",
      "headline": "Habyarimana's Coup",
      "text": "Major General Juvénal Habyarimana led a coup d'état, overthrowing President Grégoire Kayibanda and establishing a one-party state under the National Revolutionary Movement for Development (MRND)."
    },
    {
      "date": "1990-10-01",
      "headline": "Rwandan Civil War Begins",
      "text": "The Rwandan Patriotic Front (RPF), composed mainly of Tutsi exiles, invaded Rwanda from Uganda, marking the start of the Rwandan Civil War."
    },
    {
      "date": "1994-04-06",
      "headline": "Assassination of President Habyarimana",
      "text": "President Juvénal Habyarimana's plane was shot down, killing him and sparking the Rwandan Genocide, during which an estimated 800,000 Tutsi and moderate Hutu were killed over approximately 100 days."
    },
    {
      "date": "1994-07",
      "headline": "End of the Genocide",
      "text": "The Rwandan Patriotic Front (RPF) captured Kigali, effectively ending the genocide. The RPF established a new government with Pasteur Bizimungu as President and Paul Kagame as Vice President."
    },
    {
      "date": "2000-03-24",
      "headline": "Paul Kagame Becomes President",
      "text": "Paul Kagame was sworn in as President of Rwanda after the resignation of Pasteur Bizimungu."
    },
    {
      "date": "2003-08-25",
      "headline": "New Constitution Adopted",
      "text": "Rwanda adopted a new constitution, which included measures to prevent ethnic conflict and promote national unity."
    },
    {
      "date": "2015-12-18",
      "headline": "Constitutional Referendum",
      "text": "A referendum approved changes to the constitution, allowing President Paul Kagame to potentially remain in power until 2034."
    }
  ]
}

