      "date": "-322",
      "headline": "Maurya Empire",
      "text": "Chandragupta Maurya established the Maurya Empire, which included the region of present-day Uttar Pradesh."
    },
    {
      "date": "00320",
      "headline": "Gupta Empire",
      "text": "The Gupta Empire, known as the Golden Age of India, ruled over the region, contributing to advancements in science, art, and culture."
    },
